package com.cestasdamel.erp.controller; import com.cestasdamel.erp.dto.Responses.UserView; import com.cestasdamel.erp.repository.UserRepository; import lombok.RequiredArgsConstructor; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/users") @RequiredArgsConstructor public class UserController {private final UserRepository users;@GetMapping public List<UserView> list(){return users.findAll().stream().map(u->new UserView(u.getId(),u.getName(),u.getEmail(),u.isActive())).toList();}@GetMapping("/me") public UserView me(Authentication a){var u=users.findByEmailIgnoreCase(a.getName()).orElseThrow();return new UserView(u.getId(),u.getName(),u.getEmail(),u.isActive());}}
